let guildDialogActive=false;
function guildDialogMount(){let m=document.getElementById('guildDialogRoot');if(!m){m=document.createElement('div');m.id='guildDialogRoot';document.body.append(m)}return m}
function guildDialogClose(mount){if(!mount)return;mount.replaceChildren();guildDialogActive=false}
function guildDialogFrame(mount,parts,opts){mount.replaceChildren();guildDialogActive=true;const mask=document.createElement('div');mask.className='guild-dialog-mask';const box=document.createElement('div');box.className='guild-dialog-box'+(opts.tone==='warn'?' guild-dialog-warn':'');const head=document.createElement('div');head.className='guild-dialog-head';const seal=document.createElement('span');seal.className='guild-dialog-seal';seal.textContent='✦';const title=document.createElement('span');title.textContent=opts.title||'公会告示';head.append(seal,title);const body=document.createElement('div');body.className='guild-dialog-body';parts.forEach(part=>body.append(part));box.append(head,body);mount.append(mask,box);return{box,mask}}
function guildAlert(text){const mount=guildDialogMount();const p=document.createElement('p');p.className='guild-dialog-text';p.textContent=String(text);const foot=document.createElement('div');foot.className='guild-dialog-foot';const ok=document.createElement('button');ok.type='button';ok.className='guild-dialog-ok';ok.textContent='知道了';ok.onclick=()=>guildDialogClose(mount);foot.append(ok);guildDialogFrame(mount,[p,foot],{title:'公会告示'});ok.focus()}
function guildConfirmDialog(opts){return new Promise(resolve=>{const mount=guildDialogMount();const p=document.createElement('p');p.className='guild-dialog-text';p.textContent=opts.text||'';const foot=document.createElement('div');foot.className='guild-dialog-foot';const no=document.createElement('button');no.type='button';no.className='guild-dialog-no';no.textContent=opts.cancelText||'取消';no.onclick=()=>{guildDialogClose(mount);resolve(false)};const yes=document.createElement('button');yes.type='button';yes.className='guild-dialog-ok';yes.textContent=opts.okText||'确定';yes.onclick=()=>{guildDialogClose(mount);resolve(true)};foot.append(no,yes);guildDialogFrame(mount,[p,foot],{title:opts.title||'公会确认',tone:opts.tone});no.focus()})}
function guildPromptDialog(opts){return new Promise(resolve=>{const mount=guildDialogMount();const label=document.createElement('label');label.className='guild-dialog-label';label.textContent=opts.label||'';const input=document.createElement('input');input.className='guild-dialog-input';input.type='text';input.placeholder=opts.placeholder||'';input.value=opts.value||'';const foot=document.createElement('div');foot.className='guild-dialog-foot';const no=document.createElement('button');no.type='button';no.className='guild-dialog-no';no.textContent='取消';no.onclick=()=>{guildDialogClose(mount);resolve(null)};const yes=document.createElement('button');yes.type='button';yes.className='guild-dialog-ok';yes.textContent='确定';yes.onclick=()=>{const v=input.value.trim();if(opts.validate&&!opts.validate(v)){input.focus();return}resolve(v);guildDialogClose(mount)};foot.append(no,yes);guildDialogFrame(mount,[label,input,foot],{title:opts.title||'公会登记'});input.focus()})}
