 const arcane=ensureArcane(),entry=arcane.entries[key];
 if(!active){if(entry){entry.active=false;delete entry.completedAt}recordGuildLedger({ledgerKey:key,action:'撤销委托结算',jDelta:-praiseReward(key),expDelta:-(growth.entries?.[key]?.exp??raw),active:false});delete (growth.praiseSeen||{})[key];notifyGuildV4Settlement({key,title,category,grade,active:false});return null}
