 const ledger=growth.entries?.[key],original=ledger?.exp??raw,seed=[...key].reduce((n,c)=>(n*31+c.charCodeAt(0))>>>0,7);let magicExp=Math.floor(original*(15+seed%16)/100);if(original>0&&magicExp===0)magicExp=1;
 const record={active:true,magicId:Arcane.magic(title,category,grade),magicExp,levelExp:original-magicExp,completedAt,version:2,title,category};arcane.entries[key]=record;recordGuildLedger({ledgerKey:key,action:key.startsWith('project:')?'完成远征阶段':'完成委托',taskId:key.split(':')[1]||'',stageId:key.startsWith('project:')?key.split(':')[2]||'':'',jDelta:praiseReward(key),expDelta:original,active:true});
 growth.entries??={};growth.entries[key]??={exp:original,active:true};growth.entries[key].levelExp=record.levelExp;
 showGuildPraise(key,title,category,grade,praiseReward(key),original);notifyGuildV4Settlement({key,title,category,grade,active:true,completedAt});return record;
