const sRankHonorIconRegistry={research:{icon:'素材/界面/功能图标/s-rank-icon-research.png',name:'魔导研究徽记'},archive:{icon:'素材/界面/功能图标/s-rank-icon-archive.png',name:'秘卷归档徽记'},delivery:{icon:'素材/界面/功能图标/s-rank-icon-delivery.png',name:'重大交付徽记'},expedition:{icon:'素材/界面/功能图标/s-rank-icon-expedition.png',name:'远征归队徽记'},writing:{icon:'素材/界面/功能图标/s-rank-icon-writing.png',name:'星辉书写徽记'},guildService:{icon:'素材/界面/功能图标/s-rank-icon-guild-service.png',name:'公会贡献徽记'},recovery:{icon:'素材/界面/功能图标/s-rank-icon-recovery.png',name:'守护与恢复徽记'},general:{icon:'素材/界面/功能图标/s-rank-icon-general.png',name:'S级特别委托徽记'}};
function isCompletedSRankQuest(task){return!!task&&guildGrade(task)==='S'&&task.done===true&&task.status==='completed'&&!!task.completedAt&&task.status!=='cancelled'&&task.status!=='withdrawn'&&(task.type!=='project'||(task.steps||[]).length>0&&(task.steps||[]).every(step=>step.done))}
