function normalizeTaskRecords(){
 const beforeData=JSON.stringify(data),beforeTasks=JSON.stringify(tasks);let assigneeChanged=false;
 const removedStages=new Set(Object.values(growth?.v4?.eventLedger||{}).filter(row=>row.type==='stage-delete'&&!row.reversedAt).map(row=>row.taskId+'|'+row.stageId));
 for(const [d,record]of Object.entries(data)){
  record.checked??={};record.extra??=[];record.rewards??={};
  for(const [id,on]of Object.entries(record.checked))if(on&&record.rewards[id]===undefined)record.rewards[id]=amount(id);
 }
 for(const t of tasks){
   if(t.type==='project'&&!t.done&&Array.isArray(t.steps))t.steps=t.steps.filter(step=>step.done||!removedStages.has(t.id+'|'+step.id));
   t.schemaVersion=Math.max(GUILD_SCHEMA_VERSION,Number(t.schemaVersion)||0);
   t.originalText=typeof t.originalText==='string'&&t.originalText?t.originalText:String(t.title||'');
   // 新版只使用 due/dueTime；仅清理无意义的空计划字段，历史非空值保留作兼容档案。
   if(t.plannedAt==='')delete t.plannedAt;
   if(!Number.isFinite(t.estimatedMinutes))t.estimatedMinutes=Number(t.duration)||0;
   t.dependsOnTaskIds=Array.isArray(t.dependsOnTaskIds)?[...new Set(t.dependsOnTaskIds.filter(id=>id&&id!==t.id))]:[];
   if(t.blockedReason!==undefined&&typeof t.blockedReason!=='string')t.blockedReason='';
   if(!t.grade)t.grade=guildGrade(t);
   const beforeAssignee=t.assigneeId;
   ensureTaskAssignee(t);
   if(beforeAssignee!==t.assigneeId)assigneeChanged=true;
  if(t.type==='project'){
   t.steps??=[{id:'initial',title:t.title,reward:t.reward||0,done:false}];
   t.steps.forEach((step,i)=>{step.id??='step-'+i;if(step.done)step.settledJ??=step.reward});
  }
  if(t.id==='ifa-20260915'&&Object.hasOwn(data['2026-09-15']?.checked||{},'ifa')){
   t.legacyDate='2026-09-15';t.legacyId='ifa';t.legacyCounted=true;t.done=!!data[t.legacyDate].checked[t.legacyId];
  }
  if(t.type==='once'&&t.done)t.settledJ??=t.reward;
  normalizeTaskState(t);
 }
 if(assigneeChanged||beforeData!==JSON.stringify(data)||beforeTasks!==JSON.stringify(tasks))save();
}
