function urgencyBadgeHost(host){
  if(host.classList.contains('deadline'))return host.querySelector(':scope > span');
  if(host.classList.contains('backlog-row'))return host.querySelector(':scope > span');
  if(host.classList.contains('once-task-row'))return host.querySelector('.quest-meta');
  if(host.classList.contains('project-card'))return host.querySelector(':scope > small');
  if(host.classList.contains('priority-line'))return host.querySelector('.priority-link');
  return null;
}
function applyUrgencyBadge(host, task){
  if(!host||!task)return;
  if(done(task)||task.status==='cancelled'||task.status==='completed')return;
  if(!task.due)return;
  var ds=dueStamp(task);
  if(!isFinite(ds))return;
  var now=Date.now(),todayKey=today(),base=Date.parse(todayKey+'T00:00:00+08:00');
  var diffDays=Math.round((Date.parse(task.due+'T00:00:00+08:00')-base)/86400000);
  var level=null;
  if(ds<now)level='overdue';
  else if(diffDays===0)level='today';
  else if(diffDays===1)level='tomorrow';
  else if(diffDays>=2&&diffDays<=3)level='soon';
  else return;
  var txt={overdue:'已逾期',today:'今日截止',tomorrow:'明日截止',soon:'临近截止'}[level];
  var tip={overdue:'截止时间已过',today:'今天之内必须完成',tomorrow:'明天之内必须完成',soon:'距离截止不足三天'}[level];
  host.classList.add('urgency-'+level);
  var old=host.querySelector('.urgency-badge');
  if(old){old.className='urgency-badge urgency-'+level;old.textContent=txt;old.title=tip;return}
  var badge=document.createElement('small');
  badge.className='urgency-badge urgency-'+level;badge.textContent=txt;badge.title=tip;
  var box=urgencyBadgeHost(host);
  if(box)box.append(badge);
}
function applyAllUrgencyBadges(){
  document.querySelectorAll('[data-task-id]').forEach(function(node){
    if(node.classList&&node.classList.contains('project-stage-row'))return;
    var id=node.dataset.taskId,task=tasks.find(function(item){return item&&item.id===id});
    if(task)applyUrgencyBadge(node,task);
  });
}
