function stableRewardSeed(parts){return [...parts.join('|')].reduce((n,ch)=>(n*33+ch.charCodeAt(0))>>>0,5381)}
function rewardRange(type,grade){const table={daily:{F:[10,15],E:[15,20],D:[20,30],C:[30,45],B:[45,65],A:[70,95],S:[100,135]},once:{F:[15,25],E:[25,40],D:[40,65],C:[70,110],B:[130,210],A:[280,480],S:[650,1000]},project:{F:[80,120],E:[120,180],D:[180,280],C:[320,520],B:[600,900],A:[1200,1800],S:[2200,3200]}};return(table[type]||table.once)[grade]||table.once.C}
function autoReward(type,grade,due,dueTime,title,id){let [low,high]=rewardRange(type,grade);if(type==='once'&&/预约|领取|收取|确认|取件|缴费|填表/.test(title||'')){high=Math.min(high,{F:20,E:35,D:55,C:85,B:150,A:280,S:500}[grade]||high);low=Math.min(low,high)}if((type==='once'||type==='project')&&due&&dueTime)low=Math.min(high,Math.ceil(low+(high-low)*.55));const seed=stableRewardSeed([id||'',title||'',type||'',grade||'',due||'',dueTime||'']);return low+seed%(high-low+1)}
