const realCatalog=[["公会补给箱","☀️",[["小零食",5],["冰淇淋时刻",10],["喜欢的饮料",20]]],["魔导学习室","📚",[["文具补给",30],["新书基金",50],["课程或软件基金",100]]],["公会休息日","🎬",[["甜品下午茶",35],["电影之夜",50],["美食探索",60],["兴趣体验",80]]],["公会纪念品","🔥",[["妖尾周边基金",100]]],["百年任务基金","🎁",[["大心愿基金",150]]]];
function allVirtualItems(){return virtualCatalog.flatMap(g=>g.items)}
function ownedItem(item){if(item.repeatable)return false;const items=ensureArcane().items;return !!(items[item.id]||items[item.title])}
function ownedCollections(){const known=allVirtualItems().filter(ownedItem),keys=new Set(known.flatMap(i=>[i.id,i.title]));return [...known,...Object.keys(ensureArcane().items).filter(k=>!keys.has(k)).map(k=>({id:k,title:k,kind:'legacy',desc:'保留的历史收藏',iconIndex:0}))]}
function practiceStatus(item){const effect=itemPractice(item);if(!effect)return '';const items=ensureArcane().items,used=items[item.id]?.usedAt?items[item.id]:items[item.title]?.usedAt?items[item.title]:null;return used?'已用于修习 · '+localDateTime(used.usedAt)+' · +'+used.magicExp+' 魔法 EXP':'可用于修习：'+Arcane.info(effect.magicId)[2]+' · +'+effect.exp+' 魔法 EXP（一次）'}
async function buyVirtual(item){if(item._buying||ownedItem(item))return false;item._buying=true;try{if(totals().balance<item.j){showGuildValidation('可用 J 不足。');return false}const label=item.petType?'这是哈比专用补给，会消耗 ':'这是公会虚拟收藏，会消耗 ';if(!await guildConfirmDialog({text:label+item.j+' J，不计入人民币兑换或月度预算。'}))return false;if(ownedItem(item)||totals().balance<item.j)return false;if(!item.repeatable)ensureArcane().items[item.id]={date:today(),j:item.j,name:item.title};wallet.redemptions.push({id:'virtual-'+item.id+'-'+Date.now(),date:today(),j:item.j,cents:0,name:item.title,rate:wallet.rate,virtual:true,itemId:item.id});warehousePurchase(item);save();all();restoreGlobalFonts();return true}finally{item._buying=false}}
function renderShop(){
 const root=document.querySelector('#rewardShop');if(!root)return;root.replaceChildren();let saved=[];try{const raw=sessionStorage.getItem('fairytail-reward-open');const parsed=JSON.parse(raw);saved=Array.isArray(parsed)?parsed:raw?[raw]:[]}catch{}
 const open=new Set(saved),catalog=[...realCatalog.map(([name,icon,items],i)=>({id:'real-'+i,name,icon,items:items.map(([title,value])=>({title,value}))})),...virtualCatalog.map(g=>({...g,virtual:true}))];
 const bar=document.createElement('div');bar.className='reward-tools';const search=document.createElement('input');search.placeholder='搜索奖励或收藏';search.setAttribute('aria-label','搜索奖励或收藏');search.value=sessionStorage.getItem('guild-shop-query')||'';search.oninput=()=>{sessionStorage.setItem('guild-shop-query',search.value);const cursor=search.selectionStart;renderShop();const input=root.querySelector('input');input.focus();input.setSelectionRange(cursor,cursor)};bar.append(search);
 const mode=sessionStorage.getItem('guild-shop-filter')||'all';[['all','全部'],['new','未收藏'],['owned','已收藏']].forEach(([key,name])=>{const b=document.createElement('button');b.type='button';b.textContent=name;b.disabled=mode===key;b.onclick=()=>{sessionStorage.setItem('guild-shop-filter',key);renderShop()};bar.append(b)});
 [['展开全部',true],['全部收起',false]].forEach(([name,on])=>{const b=document.createElement('button');b.type='button';b.textContent=name;b.onclick=()=>{sessionStorage.setItem('fairytail-reward-open',JSON.stringify(on?catalog.map(g=>g.name):[]));renderShop()};bar.append(b)});root.append(bar);
 catalog.forEach((g,gi)=>{const found=g.items.filter(i=>i.title.includes(search.value.trim())&&(mode==='all'||(mode==='owned'?g.virtual&&ownedItem(i):!g.virtual||!ownedItem(i))));const group=document.createElement('section'),head=document.createElement('button'),body=document.createElement('div'),expanded=open.has(g.name);group.className='reward-group reward-theme-'+gi%5;head.className='reward-head';head.type='button';head.textContent=g.icon+' '+g.name+' · '+g.items.length+' 项 '+(expanded?'－':'＋');head.setAttribute('aria-expanded',String(expanded));head.setAttribute('aria-controls','reward-panel-'+g.id);head.onclick=()=>{expanded?open.delete(g.name):open.add(g.name);sessionStorage.setItem('fairytail-reward-open',JSON.stringify([...open]));renderShop()};body.id='reward-panel-'+g.id;body.className='reward-shelf reward-grid';body.hidden=!expanded;
 const more=sessionStorage.getItem('shop-more-'+g.id)==='1';found.slice(0,more?found.length:6).forEach(item=>{const card=document.createElement('article'),name=document.createElement('h4'),price=document.createElement('strong'),desc=document.createElement('p'),state=document.createElement('small'),button=document.createElement('button');card.className='reward-item';name.textContent=item.title;const j=g.virtual?item.j:item.value*wallet.rate;price.textContent=j+' J';desc.textContent=g.virtual?item.desc:'奖励预算 ¥'+item.value;const short=Math.max(0,j-totals().balance),owned=g.virtual&&ownedItem(item),used=wallet.redemptions.filter(r=>!r.virtual&&r.date.startsWith(today().slice(0,7))).reduce((n,r)=>n+r.cents,0),over=!g.virtual&&used+item.value*100>wallet.cap*100;state.textContent=g.virtual?(practiceStatus(item)||'纯收藏 · 不占公会奖励预算'):'公会奖励';button.type='button';button.disabled=!!(owned||short||over);button.textContent=owned?'已收藏 · '+(item.kind==='appearance'?'档案徽记':item.magicId?'魔法修习徽记':'公会陈列'):short?'还差 '+short+' J':over?'本月额度不足':g.virtual?'收藏道具':'兑换奖励';button.onclick=async()=>{if(g.virtual){buyVirtual(item);return}const current=wallet.redemptions.filter(r=>!r.virtual&&r.date.startsWith(today().slice(0,7))).reduce((n,r)=>n+r.cents,0);if(totals().balance<j||current+item.value*100>wallet.cap*100)return;if(!await guildConfirmDialog({text:'登记兑换「'+item.title+'」？扣除 '+j+' J，记入 ¥'+item.value+'，只是个人奖励记账，不会下单或付款。'}))return;wallet.redemptions.push({id:Date.now(),date:today(),j,cents:item.value*100,name:item.title,rate:wallet.rate,virtual:false});save();all()};if(owned&&itemPractice(item)&&!ensureArcane().items[item.id]?.usedAt&&!ensureArcane().items[item.title]?.usedAt){button.disabled=false;button.textContent='用于修习';button.onclick=()=>useVirtualForPractice(item)}else if(owned&&practiceStatus(item).startsWith('已用于'))button.textContent='已用于修习';card.append(rewardSprite(item.title,item.iconIndex),name,price,desc,state,button);body.append(card)});
 if(!found.length)body.textContent='公会仓库暂未找到这件收藏。';if(found.length>6){const b=document.createElement('button');b.type='button';b.textContent=more?'收起部分商品':'显示本类全部（'+found.length+'）';b.onclick=()=>{sessionStorage.setItem('shop-more-'+g.id,more?'0':'1');renderShop()};body.append(b)}group.append(head,body);root.append(group)})
}
function renderCollections(body,rerender){const arcane=ensureArcane(),owned=ownedCollections();arcane.displayItems??=[];const groups=virtualCatalog.map(group=>[group.name,owned.filter(item=>group.items.some(x=>x.id===item.id||x.title===item.title)).length,group.items.length]);const intro=document.createElement('p');intro.textContent='已收藏 '+owned.length+' / '+allVirtualItems().length+' 件；'+groups.map(([name,count,total])=>name+' '+count+'/'+total).join(' · ')+'。最多佩戴两个外观徽记。';body.append(intro);for(const item of owned){const row=document.createElement('p');row.className='collection-row';const text=document.createElement('span'),location=item.kind==='appearance'?'档案头像旁佩戴':item.magicId?'魔导士档案 → '+(Arcane.info(item.magicId)?.[2]||'魔法'):'公会陈列';text.textContent=item.title+' · '+item.desc+' · 展示于：'+location;row.append(rewardSprite(item.title,item.iconIndex),text);if(itemPractice(item)){const detail=document.createElement('small');detail.textContent=practiceStatus(item);row.append(detail);if(!arcane.items[item.id]?.usedAt&&!arcane.items[item.title]?.usedAt){const use=document.createElement('button');use.type='button';use.textContent='用于修习';use.onclick=async()=>{if(await useVirtualForPractice(item))rerender()};row.append(use)}}if(item.kind==='appearance'){const b=document.createElement('button'),on=arcane.displayItems.includes(item.id);b.textContent=on?'取下徽记':'佩戴徽记';b.onclick=()=>{if(on)arcane.displayItems=arcane.displayItems.filter(id=>id!==item.id);else if(arcane.displayItems.length<2)arcane.displayItems.push(item.id);else{guildAlert('最多同时展示两个外观徽记。');return}save();rerender()};row.append(b)}body.append(row)}}


const stageManagerStyle=document.createElement('style');stageManagerStyle.textContent='.stage-manager{display:flex;flex-wrap:wrap;gap:7px;margin:9px 0;padding:9px;border:1px solid #ead1b4;border-radius:9px;background:#fff9f0}.stage-manager input{flex:1;min-width:160px;min-height:30px;padding:5px 8px}.stage-manager button{min-height:30px;padding:5px 9px;font-size:12px}.stage-remove{margin-left:auto;min-height:25px!important;padding:3px 6px!important;font-size:11px;font-size:11px!important}.project-card .project-actions{margin:8px 0}.project-card .row{align-items:flex-start}.project-next{display:block;margin:5px 0;color:#8d5637}';document.head.append(stageManagerStyle);
function redistributeOpenSteps(task){const settled=(task.steps||[]).filter(step=>step.done).reduce((sum,step)=>sum+(Number(step.settledJ??step.reward)||0),0);return distributePhaseRewards(task.steps||[],task.reward,settled)}
function renderStageManager(task,host){
 if(task.done||task.status==='completed')return;const existing=host.querySelector('.stage-manager');if(existing){existing.remove();return}
 const box=document.createElement('form'),input=document.createElement('input'),add=document.createElement('button'),rebalance=document.createElement('button');box.className='stage-manager';input.placeholder='新阶段的具体目标';input.maxLength=80;input.required=true;add.type='submit';add.textContent='新增阶段';rebalance.type='button';rebalance.textContent='重分未完成阶段酬劳';const tools=document.createElement('div');tools.className='stage-manager-tools';tools.append(input,add,rebalance);box.append(tools);
 const refresh=()=>{save();all();const next=document.getElementById('quest-'+task.id);if(next)renderStageManager(task,next)};
 box.onsubmit=e=>{e.preventDefault();const title=input.value.trim();if(!title)return;if((task.steps||[]).length>=12){showGuildValidation('阶段最多 12 个，请先整理或删除未完成阶段。');return}const settled=(task.steps||[]).filter(step=>step.done).reduce((sum,step)=>sum+(Number(step.settledJ??step.reward)||0),0),open=(task.steps||[]).filter(step=>!step.done);if(Number(task.reward)-settled<open.length+1){showGuildValidation('剩余酬劳不足，无法新增阶段；原总酬劳保持不变。');return}task.steps??=[];const id='step-'+(globalThis.crypto?.randomUUID?.()||Date.now()+'-'+task.steps.length);task.steps.push({id,title,reward:0,done:false});redistributeOpenSteps(task);refresh()};
 rebalance.onclick=()=>{if(!redistributeOpenSteps(task)){showGuildValidation('剩余酬劳不足以重分。');return}refresh()};
 (task.steps||[]).forEach(step=>{const row=document.createElement('div'),title=document.createElement('input'),remove=document.createElement('button');row.className='stage-manager-entry';title.value=step.title;title.maxLength=80;title.setAttribute('aria-label','阶段名称');title.disabled=!!step.done;title.onchange=()=>{const value=title.value.trim();if(!value){title.value=step.title;return}step.title=value;save()};remove.type='button';remove.textContent=step.done?'已完成 · 保留':'删除阶段';remove.disabled=!!step.done;remove.title=step.done?'该阶段已有完成记录；请先使用原有撤销完成流程。':'删除此未完成阶段';remove.onclick=async()=>{if(step.done||task.done)return;if((task.steps||[]).length<=1){showGuildValidation('远征至少保留一个阶段。');return}if(!await guildConfirmDialog({text:'删除未完成阶段「'+step.title+'」？整项远征总酬劳不变。'}))return;globalThis.GuildV4?.recordV4Event('stage-delete:'+task.id+':'+step.id,{type:'stage-delete',taskId:task.id,stageId:step.id});task.steps=task.steps.filter(item=>item.id!==step.id);redistributeOpenSteps(task);refresh()};row.append(title,remove);box.append(row)});host.insertBefore(box,host.querySelector('.row')||null);
}
