function requestTaskOutcome(task,onContinue){let dialog=document.querySelector('#taskOutcomeDialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='taskOutcomeDialog';dialog.className='task-outcome-dialog';dialog.innerHTML='<form method="dialog"><button type="button" class="task-outcome-close" aria-label="关闭">×</button><h3>将委托成果收入公会档案</h3><p class="muted task-outcome-title"></p><label>实际完成了什么？<textarea name="summary" maxlength="300" rows="3" placeholder="可选，例如：整理了 36 组实验数据并重新编号"></textarea></label><label>下一步是什么？<textarea name="nextStep" maxlength="200" rows="2" placeholder="可选，例如：明天检查异常值"></textarea></label><div class="task-outcome-actions"><button type="button" data-action="skip">跳过并完成</button><button value="confirm" class="action-primary">保存成果并完成</button></div></form>';document.body.append(dialog)}dialog._opener=document.activeElement;dialog.onclose=()=>dialog._opener?.focus();const form=dialog.querySelector('form'),summary=form.elements.summary,nextStep=form.elements.nextStep;dialog.querySelector('.task-outcome-title').textContent='「'+task.title+'」';summary.value=task.outcome?.summary||'';nextStep.value=task.outcome?.nextStep||'';let committed=false;const finish=saveOutcome=>{if(committed)return;committed=true;if(saveOutcome&&(summary.value.trim()||nextStep.value.trim()))task.outcome={summary:summary.value.trim(),nextStep:nextStep.value.trim(),recordedAt:nowShanghai()};dialog.close();onContinue()};form.onsubmit=event=>{event.preventDefault();finish(true)};dialog.querySelector('[data-action="skip"]').onclick=()=>finish(false);dialog.oncancel=()=>{committed=true};dialog.querySelector('.task-outcome-close').onclick=()=>{committed=true;dialog.close()};dialog.showModal()}
function completeOnceTask(t,outcomeConfirmed=false){
 if(t.done||t.status==='cancelled'||!t.acceptedAt)return;
 if(!taskDependenciesComplete(t)){guildAlert('请先完成前置委托。');return}if(t.blockedReason){guildAlert('这项委托仍标记为「'+t.blockedReason+'」，请先在修订委托中解除阻塞。');return}
 if(!outcomeConfirmed){requestTaskOutcome(t,()=>completeOnceTask(t,true));return}
 createGuildSnapshot('完成委托前 · '+t.title);
 t.done=true;t.status='completed';t.settledJ??=t.reward;t.completedAt??=nowShanghai();if(t.assigneeVisual?.source==='state')t.assigneeVisual.state='completed';
 settleArcane(t.legacyCounted?'daily:'+t.legacyDate+':'+t.legacyId:'task:'+t.id,t.title,t.category,GuildGrowth.points[guildGrade(t)],true,guildGrade(t));
 if(t.legacyCounted){data[t.legacyDate].checked[t.legacyId]=true;data[t.legacyDate].completedAt??={};data[t.legacyDate].completedAt[t.legacyId]=t.completedAt}
 if(['A','S'].includes(guildGrade(t))){ensureGuildCelebration(t);localStorage.setItem('fairytail-guild-hall-active-scene','mainHall');localStorage.setItem('fairytail-guild-hall-open','1')}save();all();if(!['A','S'].includes(guildGrade(t)))showGuildPraise('task:'+t.id,t.title,t.category,guildGrade(t),t.settledJ??t.reward,GuildGrowth.points[guildGrade(t)])
}function completeProjectStage(task,step){
 if(!task||!step||step.done||!task.acceptedAt||task.status==='cancelled')return false;
 if(!taskDependenciesComplete(task)){guildAlert('请先完成这次远征的前置委托。');return false}if(task.blockedReason){guildAlert('这次远征仍标记为「'+task.blockedReason+'」，请先解除阻塞。');return false}
 const nextStage=(task.steps||[]).find(item=>!item.done);if(nextStage!==step){guildAlert('请先完成前一段远征。');return false}
 createGuildSnapshot('完成远征阶段前 · '+step.title);
 const view=captureGuildViewState(task.id),exp=growth?.projectPools?.[task.id]?.shares?.[step.id]??0;
 step.done=true;step.settledJ??=step.reward;step.completedAt??=nowShanghai();
 settleArcane('project:'+task.id+':'+step.id,step.title,task.category,exp,true,guildGrade(task));save();all();restoreGuildViewState(view);return true
}
function completeProjectQuest(task,button,outcomeConfirmed=false){
 if(!task||task.done||task.status==='completed'||task.status==='cancelled'||!(task.steps||[]).length||!task.steps.every(step=>step.done))return false;
 if(!outcomeConfirmed){requestTaskOutcome(task,()=>completeProjectQuest(task,button,true));return false}
 createGuildSnapshot('完成长期远征前 · '+task.title);
 if(button)button.disabled=true;const view=captureGuildViewState(task.id);task.done=true;task.status='completed';task.completedAt??=nowShanghai();task.projectCompletionLedgerKey??='project-complete:'+task.id+':'+task.completedAt;if(['A','S'].includes(guildGrade(task))){ensureGuildCelebration(task);localStorage.setItem('fairytail-guild-hall-active-scene','mainHall');localStorage.setItem('fairytail-guild-hall-open','1')}save();all();
 const close=()=>restoreGuildViewState(view);if(['A','S'].includes(guildGrade(task))){const notice=document.createElement('div');notice.className='guild-praise guild-praise--notice';notice.setAttribute('role','status');notice.dataset.grade=guildGrade(task);notice.innerHTML='<div class="guild-praise-copy"><strong>公会大厅已为归队庆典点亮</strong><span>前往左侧公会实景，点击“举行归队庆典”。</span></div>';document.body.append(notice);setTimeout(()=>notice.remove(),5200);close()}else{const exp=(task.steps||[]).reduce((sum,step)=>sum+(growth?.projectPools?.[task.id]?.shares?.[step.id]??0),0);showGuildPraise('task:'+task.id,task.title,task.category,guildGrade(task),task.reward,exp);close()}return true
}
