function ensureWarehouse(){
 const w=guildWarehouse&&typeof guildWarehouse==='object'?guildWarehouse:(guildWarehouse={});w.version=Math.max(2,Number(w.version)||1);w.items=Array.isArray(w.items)?w.items:[];w.locations=Array.isArray(w.locations)?w.locations:[];w.movements=Array.isArray(w.movements)?w.movements:[];w.migrationIds=w.migrationIds&&typeof w.migrationIds==='object'?w.migrationIds:{};w.happy=w.happy&&typeof w.happy==='object'?w.happy:{};w.happy.exp=Number.isSafeInteger(w.happy.exp)&&w.happy.exp>=0?w.happy.exp:0;w.happy.interactions=Array.isArray(w.happy.interactions)?w.happy.interactions:[];w.happy.equipped=Array.isArray(w.happy.equipped)?w.happy.equipped.slice(0,2):[];w.happy.mood=typeof w.happy.mood==='string'?w.happy.mood:'精神不错';w.happy.hunger=Number.isFinite(w.happy.hunger)?Math.max(0,Math.min(100,Math.round(w.happy.hunger))):80;w.happy.moodValue=Number.isFinite(w.happy.moodValue)?Math.max(0,Math.min(100,Math.round(w.happy.moodValue))):75;w.happy.wish=w.happy.wish&&typeof w.happy.wish==='object'?w.happy.wish:null;w.happy.lastNeedDay=typeof w.happy.lastNeedDay==='string'?w.happy.lastNeedDay:today();w.happy.displayState=typeof w.happy.displayState==='string'?w.happy.displayState:'';w.happy.displayUntil=Number(w.happy.displayUntil)||0;applyHappyNeeds(w);
 warehouseDefaultLocations.forEach(([id,title])=>{if(!w.locations.some(location=>location.id===id))w.locations.push({id,title,archived:false,system:true,createdAt:warehouseTime()})});
 allVirtualItems().forEach(item=>{const entry=warehouseItemFromCatalog(item);if(!w.items.some(existing=>existing.id===entry.id))w.items.push(entry)});
 if(typeof ownedCollections==='function')for(const item of ownedCollections()){
   const id=item.id||'legacy-'+encodeURIComponent(item.title);if(w.migrationIds[id])continue;const entry=w.items.find(existing=>existing.id===id)||warehouseItemFromCatalog(item);if(!w.items.some(existing=>existing.id===entry.id))w.items.push(entry);w.movements.push({id:'migration-'+id,itemId:id,action:'in',quantity:1,fromLocationId:'',toLocationId:entry.defaultLocationId,occurredAt:warehouseTime(),note:'由已有虚拟收藏迁入',source:'历史迁移',sourceId:id});w.migrationIds[id]=warehouseTime();
 }
 return w
}
function warehouseItem(id){return ensureWarehouse().items.find(item=>item.id===id)}
function warehouseStock(id,locationId=''){const movements=ensureWarehouse().movements;return movements.reduce((total,movement)=>{if(movement.itemId!==id)return total;if(movement.action==='in'&&(!locationId||movement.toLocationId===locationId))return total+movement.quantity;if(movement.action==='out'&&(!locationId||movement.fromLocationId===locationId))return total-movement.quantity;if(movement.action==='move'){if(!locationId)return total;if(movement.toLocationId===locationId)return total+movement.quantity;if(movement.fromLocationId===locationId)return total-movement.quantity}if(movement.action==='adjust'&&(!locationId||movement.toLocationId===locationId))return total+(movement.direction==='out'?-movement.quantity:movement.quantity);return total},0)}
function warehouseRecord(input){const w=ensureWarehouse(),quantity=Number(input.quantity);if(!Number.isSafeInteger(quantity)||quantity<1)return false;w.movements.push({id:'warehouse-'+Date.now()+'-'+(w.movements.length+1),itemId:input.itemId,action:input.action,quantity,fromLocationId:input.fromLocationId||'',toLocationId:input.toLocationId||'',occurredAt:warehouseTime(),note:(input.note||'').slice(0,120),source:input.source||'手工登记',sourceId:input.sourceId||'',direction:input.direction});return true}
function warehousePurchase(item){const entry=warehouseItem(item.id)||warehouseItemFromCatalog(item);const w=ensureWarehouse();if(!w.items.some(existing=>existing.id===entry.id))w.items.push(entry);warehouseRecord({itemId:entry.id,action:'in',quantity:1,toLocationId:entry.defaultLocationId,source:'虚拟收藏兑换',sourceId:item.id,note:'兑换后自动入库'});save()}
