function applyHappyNeeds(w){const h=w.happy,nowDay=today();if(!h.lastNeedDay){h.lastNeedDay=nowDay}if(h.lastNeedDay!==nowDay){const days=Math.max(1,Math.min(7,Math.round((new Date(nowDay+'T00:00:00')-new Date(h.lastNeedDay+'T00:00:00'))/86400000)));h.hunger=Math.max(0,h.hunger-days*8);h.moodValue=Math.max(0,h.moodValue-days*5);h.lastNeedDay=nowDay}if(h.wish&&h.wish.expiresAt&&h.wish.expiresAt<nowDay)h.wish=null;if(!h.wish&&h.wishCheckedDay!==nowDay){const threshold=(Number(h.wishMissDays)||0)>=7?800:300,roll=stableRewardSeed([nowDay,'happy-wish',String(h.exp)])%10000;h.wishCheckedDay=nowDay;if(roll<threshold&&h.hunger>35&&h.moodValue>35){const pick=happyWishPool[stableRewardSeed([nowDay,String(h.interactions.length),'pick'])%happyWishPool.length],until=new Date(nowDay+'T00:00:00+08:00');until.setDate(until.getDate()+3);h.wish={itemId:pick[0],title:pick[1],createdAt:warehouseTime(),expiresAt:until.toISOString().slice(0,10)};h.wishMissDays=0}else h.wishMissDays=(Number(h.wishMissDays)||0)+1}h.mood=h.hunger<=20?'有点饿':h.hunger<=45?'想吃点东西':h.moodValue<=25?'有点无聊':h.moodValue<=50?'想玩一会儿':h.moodValue>=85?'很开心':'精神不错'}
