async function recordIncomplete(task,step){const reason=await guildPromptDialog({title:'记录未完成',label:'原因或下一步（最多 120 字）'});if(reason===null)return;const target=step||task;if(target.incompleteAt)return;target.incompleteAt=nowShanghai();target.incompleteReason=String(reason).trim().slice(0,120);target.outcome='incomplete';growth??={};growth.incompleteRecords??={};const key=step?'project:'+task.id+':'+step.id:'task:'+task.id;growth.incompleteRecords[key]={key,title:step?.title||task.title,category:task.category,at:target.incompleteAt,reason:target.incompleteReason};save();all();guildAlert('本次未完成已记录；不会扣除 J 或经验，可以在详情中重新安排。')}
function ensureOutcomeButtons(){document.querySelectorAll('.once-quests .row[id^="quest-"]:not(.is-folded)').forEach(row=>{const task=tasks.find(item=>'quest-'+item.id===row.id),actions=row.querySelector('.once-actions');if(!task||!actions||!task.acceptedAt||done(task)||task.incompleteAt||actions.querySelector('.outcome-incomplete'))return;const button=document.createElement('button');button.type='button';button.className='action-secondary outcome-incomplete';button.textContent='本次未完成';button.onclick=event=>{event.stopPropagation();recordIncomplete(task)};actions.append(button)});document.querySelectorAll('.project-card:not(.is-folded)').forEach(card=>{const task=tasks.find(item=>'quest-'+item.id===card.id),actions=card.querySelector('.project-actions'),step=task?.steps?.find(item=>!item.done&&!item.incompleteAt);if(!task||!actions||!task.acceptedAt||!step||actions.querySelector('.outcome-incomplete'))return;const button=document.createElement('button');button.type='button';button.className='action-secondary outcome-incomplete';button.textContent='本次未完成';button.onclick=event=>{event.stopPropagation();recordIncomplete(task,step)};actions.append(button)})}
function ensureFoldedCompletionButtons(){
 document.querySelectorAll('[id^="quest-"].is-folded').forEach(card=>{
  const task=tasks.find(item=>'quest-'+item.id===card.id);
  if(!task||!task.acceptedAt||done(task)||task.status==='cancelled'||!task.startedAt||card.querySelector('.folded-complete'))return;
  const host=card.querySelector('.quest-fold-summary')||card.querySelector('h3');if(!host)return;
  const button=document.createElement('button');button.type='button';button.className='action-complete folded-complete';button.textContent=task.type==='project'?'完成当前阶段':'完成委托';
  button.onclick=event=>{
   event.stopPropagation();
   if(task.type==='project'){
    const step=task.steps?.find(item=>!item.done);if(step)completeProjectStage(task,step);
   }else completeOnceTask(task,true);
  };
  host.append(button)
 })
}
