function toggleHappyQuickMenu(){const card=document.querySelector('#happyCorner');if(!card)return;const old=card.querySelector('.happy-quick-menu');if(old){old.remove();return}const menu=document.createElement('div'),items=happyAvailableItems();menu.className='happy-quick-menu';if(!items.length){const empty=document.createElement('span'),buy=document.createElement('button');empty.textContent='补给袋暂无可用物品';buy.type='button';buy.textContent='去采购哈比补给';buy.className='happy-procure';buy.onclick=()=>openHappyProcurement(buy);menu.append(empty,buy)}else items.forEach(item=>{const button=document.createElement('button'),count=warehouseStock(item.id);button.type='button';button.textContent=(item.petType==='food'?'喂给哈比 · ':'陪哈比玩 · ')+item.title+' · 剩余 '+count;button.onclick=()=>useHappyItem(item);menu.append(button)});card.append(menu)}
function maybeShowHappyWish(){const w=ensureWarehouse(),wish=w.happy.wish;if(!wish||wish.dialogSeenAt)return;const item=happyCatalog.find(x=>x.id===wish.itemId);if(!item)return;wish.dialogSeenAt=warehouseTime();save();let dialog=document.querySelector('#happyWishDialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='happyWishDialog';dialog.className='happy-wish-dialog';document.body.append(dialog)}dialog.replaceChildren();const close=document.createElement('button'),copy=document.createElement('div'),actions=document.createElement('div');close.type='button';close.className='dialog-close';close.textContent='×';close.setAttribute('aria-label','关闭哈比心愿');close.onclick=()=>dialog.close();copy.className='happy-wish-copy';copy.append(happyAvatar(46,w),Object.assign(document.createElement('strong'),{textContent:'哈比想要：'+item.title}),Object.assign(document.createElement('p'),{textContent:'哈比看着补给袋，似乎想尝一口这个。'}));const stock=warehouseStock(item.id,warehouseItem(item.id)?.defaultLocationId),primary=document.createElement('button'),later=document.createElement('button');primary.type=later.type='button';primary.textContent=stock>0?'满足心愿':'去采购';primary.onclick=()=>{dialog.close();stock>0?useHappyItem(item):openHappyProcurement(primary)};later.textContent='以后再说';later.onclick=()=>dialog.close();actions.className='happy-wish-actions';actions.append(primary,later);dialog.append(close,copy,actions);if(typeof dialog.showModal==='function'&&!dialog.open)dialog.showModal()}
