function makeScrollableList(host,rows){if(!host||host.querySelector(':scope > .task-scroll-list'))return;const list=document.createElement('div');list.className='task-scroll-list';rows.forEach(row=>list.append(row));host.append(list);if(rows.length>4)list.classList.add('is-scrollable')}
function applyTaskListScrolling(){document.querySelectorAll('.guild-content .grid>.card').forEach(card=>{const rows=[...card.children].filter(node=>node.classList?.contains('row'));if(rows.length)makeScrollableList(card,rows)});const once=document.querySelector('.once-task-list');if(once&&once.querySelectorAll(':scope>.row').length>4)once.classList.add('is-scrollable');else once?.classList.remove('is-scrollable');const projectsRoot=document.querySelector('#projects');if(projectsRoot){const projects=[...projectsRoot.children].filter(node=>node.classList?.contains('project-card'));projectsRoot.classList.toggle('is-scrollable',projects.length>4)}document.querySelectorAll('.project-card').forEach(card=>{const stages=[...card.children].filter(node=>node.classList?.contains('row'));if(stages.length>4)makeScrollableList(card,stages)})}
function compactTemporaryCard(){const cards=[...document.querySelectorAll('.guild-content .grid>.card')],card=cards.find(item=>item.querySelector('h2')?.textContent.includes('临时委托记录'));if(!card||card.dataset.compactReady)return;card.dataset.compactReady='1';const rows=[...card.querySelectorAll('.row')],unfinished=rows.filter(row=>!row.querySelector('input:checked')),finished=rows.filter(row=>row.querySelector('input:checked')),keep=new Set([...unfinished.slice(0,3),...finished.slice(0,2)]),hidden=rows.filter(row=>!keep.has(row));if(!hidden.length)return;hidden.forEach(row=>row.hidden=true);const toggle=document.createElement('button');toggle.type='button';toggle.className='compact-more';toggle.textContent='展开其余 '+hidden.length+' 项';toggle.onclick=()=>{const expanded=toggle.dataset.expanded==='1';hidden.forEach(row=>row.hidden=expanded);toggle.dataset.expanded=expanded?'0':'1';toggle.textContent=expanded?'展开其余 '+hidden.length+' 项':'收起其余委托'};card.querySelector('h2')?.append(document.createTextNode(' · '+rows.length+' 项'));card.append(toggle)}
